#!/usr/bin/env python3
"""Build a framework-free static site. Run: python3 build.py"""
from pathlib import Path
from html import escape as e
from content import TASKS, ARTISTS, ARTIST_GROUPS, NZQA, SPEC
from lessons import build_lesson_pages

OUT = Path(__file__).parent / 'dist'
OUT.mkdir(exist_ok=True)
CHECKED = '22 November 2026'
LEVELS = {
 1: dict(title='Look. Try. Resolve.',description='Get to know your materials, follow your curiosity and make work that means something to you.',colour='cobalt',image='gully',note='Current Visual Arts standards, taught through painting. These replace the retired Level 1 painting standards.',words='Observe & explore'),
 2: dict(title='Follow an idea further.',description='Choose your painting language. Connect your drawings. Turn useful discoveries into a purposeful body of work.',colour='orange',image='cezanne',note='Painting-specific standards. Drawing includes painted studies, colour investigations and other ways of thinking visually.',words='Develop & extend'),
 3: dict(title='Make the language yours.',description='Work with intention, revisit your discoveries and bring your ideas and methods together in a personal painting practice.',colour='magenta',image='hodgkins',note='Painting-specific standards. Regeneration matters across the external body of work, including at Achievement.',words='Integrate & regenerate')
}
def filename(t): return 'task-'+t['ref'].replace('.','-')+'.html'
def level(t): return int(t['ref'][0])
def standard_url(t): return f"https://www.nzqa.govt.nz/nqfdocs/ncea-resource/achievements/{'2024' if level(t)==1 else '2019'}/as{t['as_id']}.pdf"
def spec_url(t): return SPEC+str(t['as_id'])+'-spc-2026.pdf'
def exemplar_url(t):
 if t['as_id'] == 91913:
  return NZQA + 'as-91913-annotated-exemplars/'
 return NZQA + ('as-'+str(t['as_id'])+'/' if t['assessment']=='Internal' else '')
def link(url,text,cls=''): return f'<a class="{cls}" href="{e(url,quote=True)}">{text}</a>'
def figure(key,cls='',lazy=True):
 a=ARTISTS[key]
 return f'''<figure class="artwork {cls}"><a href="{e(a['url'],quote=True)}" aria-label="View {e(a['name'])} at the source"><img src="assets/{a['image']}" alt="{e(a['alt'])}" {'loading="lazy"' if lazy else 'fetchpriority="high"'} width="800" height="620"></a><figcaption><strong>{e(a['name'])}</strong> <cite>{e(a['caption'])}</cite><span>{e(a['credit'])} {link(a['rights'],'Image source & rights')}</span></figcaption></figure>'''
def shell(title,body,current='',bodyclass='',additional_css='',description='Painting tasks for NCEA Levels 1, 2 and 3. NZQA references, artist connections and printable student task sheets.'):
 extra_css=f'<link rel="stylesheet" href="{e(additional_css,quote=True)}">' if additional_css else ''
 nav=''.join(link(f'level-{i}.html',f'Level {i}','current' if current==str(i) else '') for i in LEVELS)
 return f'''<!doctype html>
<html lang="en-NZ"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="description" content="{e(description,quote=True)}"><meta name="theme-color" content="#f4f0e9"><title>{e(title)} · The Painting Room</title><link rel="icon" href="assets/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="assets/site.css">{extra_css}<script defer src="assets/site.js"></script></head>
<body class="{bodyclass}"><a class="skip-link" href="#main">Skip to content</a><header class="masthead"><div class="masthead-inner"><a class="brand" href="index.html" aria-label="The Painting Room home">the painting<span>room<span class="brand-dot" aria-hidden="true">.</span></span></a><nav aria-label="Main navigation">{nav}{link('artists.html','Artists','current' if current=='artists' else '')}{link('teacher.html','For teachers','current' if current=='teacher' else '')}</nav></div></header>
{body}
<footer class="site-footer"><div><a class="footer-name" href="index.html">The Painting Room.</a><p>A space for ideas, experiments and paint.<br>NCEA Painting · Aotearoa New Zealand</p></div><div><p>Independent teaching resources, informed by NZQA.<br>Sources checked {CHECKED}.</p><p>{link('teacher.html#sources','Standards & sources')} · {link('artists.html#image-rights','Image credits')} · <a href="#main">Back to top</a></p></div></footer></body></html>'''
def write(name,title,body,**kw): (OUT/name).write_text(shell(title,body,**kw),encoding='utf-8')
def row(t):
 return f'''<tr data-level="{level(t)}" data-search="{e((t['ref']+' '+str(t['as_id'])+' '+t['title']+' '+t['short']+' '+t['assessment']).lower(),quote=True)}"><th scope="row"><a href="{filename(t)}" class="ref ref-{level(t)}">{t['ref']}</a></th><td><a class="task-link" href="{filename(t)}">{e(t['title'])}</a><span class="row-subtitle">{e(t['short'])}</span></td><td><span class="standard">AS{t['as_id']}</span><span class="row-subtitle">{t['credits']} credits · {t['assessment']}</span></td><td>{link(filename(t),'Open sheet','text-action')}</td></tr>'''
def table(tasks):
 return '<div class="table-wrap"><table class="task-table"><caption class="sr-only">Painting task sheets by achievement standard</caption><thead><tr><th scope="col">Standard</th><th scope="col">Task sheet</th><th scope="col">Assessment</th><th scope="col"><span class="sr-only">Open</span></th></tr></thead><tbody>'+''.join(row(t) for t in tasks)+'</tbody></table></div>'
chapter_links=''.join(f'''<a class="chapter chapter-{i}" href="level-{i}.html"><span>Level {i}</span><strong>{d['words']}</strong><span class="chapter-small">{i}.2 · {i}.3 · {i}.4</span></a>''' for i,d in LEVELS.items())
write('index.html','NCEA painting task sheets',f'''<main id="main"><section class="cover"><div class="cover-copy"><h1>Good ideas<br>grow through<br><em>painting.</em></h1><p>Choose a starting point. Try something out.<br>Build a body of work that feels like yours.</p><p class="cover-context">NCEA Painting task sheets<br>Levels 1, 2 & 3 · Grounded in NZQA standards</p><a class="button button-dark" href="#task-library">Find your task sheet</a></div>{figure('hodgkins','cover-art',False)}</section><nav class="chapters" aria-label="Choose an NCEA level">{chapter_links}</nav><section id="task-library" class="section library"><div class="section-intro"><h2>A place to begin.</h2><p>Nine practical briefs. One achievement standard per sheet. Each one connects looking, making and reflecting.</p></div><form class="filters js-only" role="search"><div><label for="task-search">Find a task or standard</label><input type="search" id="task-search" placeholder="Try 1.3, AS91316 or ‘ideas’"></div><div><label for="level-filter">NCEA level</label><select id="level-filter"><option value="all">All levels</option><option value="1">Level 1</option><option value="2">Level 2</option><option value="3">Level 3</option></select></div><p id="filter-count" role="status">9 task sheets</p></form>{table(TASKS)}<div id="no-results" class="empty-state" hidden><h3>No matching task sheets</h3><p>Try a standard number, a shorter search or another level.</p><button type="button" id="reset-filters" class="button">Show all task sheets</button></div><p class="source-note">Level 1 uses the current Visual Arts standards with a painting focus. Activity quantities and teaching times are suggestions. External submission notes use the 2026 specifications; check the requirements for your assessment year.</p></section><section class="looking-strip"><h2>Look closely.<br>Borrow a method.<br>Find your own response.</h2><div><p>Explore contemporary Māori, Aotearoa and international painters. Investigate how they organise space, handle colour and let one idea lead to another.</p>{link('artists.html','Explore the artist connections','button button-dark')}<p class="small">Artist works are study references. The task sheets ask you to generate your own imagery.</p></div></section></main>''')
for i,d in LEVELS.items():
 ts=[t for t in TASKS if level(t)==i]
 featured={1:['green','gossage','fadojutimi'],2:['cotton','bush','mehretu'],3:['karaka','rewiri','hindin','bradford']}[i]
 model_links=' · '.join(link('artists.html#'+k,e(ARTISTS[k]['name'])) for k in featured)
 body=f'''<main id="main" class="level-page level-{i}"><div class="breadcrumbs">{link('index.html','All levels')}<span>/</span>Level {i}</div><section class="level-cover"><div><h1><span class="level-title">Level {i}.</span>{d['title']}</h1><p class="lead">{d['description']}</p><p>{d['note']}</p><a class="button button-dark" href="#level-tasks">Choose a task sheet</a></div>{figure(d['image'],'',False)}</section><section class="section" id="level-tasks"><div class="section-intro"><h2>Your Level {i} workbook.</h2><p>Open a sheet for the brief, studio sequence, evidence guide and printable version.</p></div>{table(ts)}<div class="learning-order"><h3>Contemporary artist connections</h3><p>{model_links}</p><h3>Connect the learning</h3><p>{'Experiment in 1.3, develop a finished series in 1.4, and give a separate substantial outcome the time it needs in 1.2. The labels are standard references, not a required teaching order.' if i==1 else 'Investigate conventions in '+str(i)+'.2, develop ideas through '+str(i)+'.3, and build the sustained external inquiry in '+str(i)+'.4. Teaching can connect across standards; evidence and assessment judgements must remain clear.'}</p></div></section><section class="plain-band"><h2>Keep your decisions visible.</h2><p>Draw from what you know. Date your studies. Record what you change and why. Your own visual thinking is the thread through every sheet.</p>{link('teacher.html','Read the assessment & teaching notes','text-action')}</section></main>'''
 write(f'level-{i}.html',f'Level {i} painting',body,current=str(i),bodyclass=f'theme-{i}')

def artist_connection(key):
 a=ARTISTS[key]
 detail = ' · '+link('artists.html#'+key,'Painting investigation') if a.get('investigation') else ''
 return f'''<li><h3>{link(a['url'],e(a['name']))}</h3><p class="artist-place">{e(a['place'])}</p><p>{e(a['focus'])}</p><p class="small model-source">{e(a.get('source_label','Artist resource'))}{detail}</p></li>'''
def submission(t):
 ref=t['ref']
 if t['assessment']=='Internal':
  return f'<p>Your teacher will confirm the assessment window, support available, final evidence and local authenticity procedures. This sheet is an original teaching resource; it is not an NZQA-issued assessment. {link(exemplar_url(t),"Compare NZQA’s annotated exemplars")}.</p>'
 notes={
 '1.3':'The 2026 workbook route uses eight single-sided A3 pages, digitised into one PDF. A slideshow alternative is limited to eight slides and 120 seconds. Include developmental evidence rather than resolved works. Your teacher manages verification submission; the submitted evidence must be self-contained.',
 '1.4':'The 2026 painting route is one landscape A1 panel, photographed for digital submission. The alternative moving-image route is limited to 60 seconds. Your teacher manages school grading and NZQA verification. Choose the format with your teacher before making the final work.',
 '2.4':'For the 2026 painting route, present two hinged portrait panels, each 820 × 610 mm. The teacher grades the work and selected portfolios are photographed for NZQA verification. This is digital submission of the physical portfolio, not physical dispatch. An actual time-based moving-image option is limited to 120 seconds.',
 '3.4':'For the 2026 physical painting route, submit three hinged portrait panels, each 820 × 610 mm; the folded portfolio must be within 1 kg and 15 mm. All paint must be dry. The alternative actual time-based moving-image route is one video up to 180 seconds, with an authenticity statement. A filmed slideshow of boards is not that alternative.'}
 return f'<p>{notes[ref]}</p><p>{link(spec_url(t),"Read the full 2026 NZQA specifications (PDF)")} and {link("teacher.html#external-conditions","external assessment conditions")}. These are year-specific requirements; confirm any updates for your assessment year.</p>'
for t in TASKS:
 i=level(t);ref=t['ref'];slug=ref.replace('.','-')
 toc=[('brief','The brief'),('artists','Artist connections'),('studio','Studio sequence'),('evidence','Evidence checklist'),('grades','Grade guide'),('reflect','Pause & reflect'),('teacher-notes','Teacher notes'),('sources','NZQA sources')]
 phases=''.join(f'<li><h3>{e(h)}</h3><p>{e(p)}</p></li>' for h,p in t['phases'])
 checklist=''.join(f'<li><label><input type="checkbox" data-save="evidence-{n}"><span>{e(p)}</span></label></li>' for n,p in enumerate(t['evidence']))
 grades=''.join(f'<tr><th scope="row">{g}</th><td>{e(p)}<span class="grade-example"><strong>In this task:</strong> {e(x)}</span></td></tr>' for g,p,x in t['grades'])
 first_image=next(k for k in t['artists'] if ARTISTS[k].get('image'))
 ext=f'''<p class="assessment-note">This is an external standard. Use the activities as teaching suggestions; make your own decisions during assessed work. Your teacher must keep support within NZQA’s annual conditions.</p>''' if t['assessment']=='External' else ''
 body=f'''<main id="main" class="task-page level-{i}" data-sheet="{ref}"><div class="breadcrumbs">{link('index.html','All levels')}<span>/</span>{link(f'level-{i}.html',f'Level {i}')}<span>/</span>Task {ref}</div><header class="task-heading"><div class="task-number">{ref}</div><div><h1>{e(t['title'])}</h1><p class="task-purpose">{e(t['short'])}</p><p class="official-title">{e(t['official'])}</p><ul class="metadata"><li>AS{t['as_id']} · v{t['version']}</li><li>{t['credits']} credits</li><li>{t['assessment']}</li><li>Painting focus</li></ul></div></header><div class="task-toolbar js-only"><button class="button button-dark print-button" type="button">Print / save as PDF</button><label class="print-option"><input type="checkbox" id="include-teacher"> Include teacher notes in print</label></div><div class="task-layout"><aside class="sheet-navigation"><nav aria-label="On this sheet"><p>On this sheet</p><ul>{''.join(f'<li><a href="#{a}">{b}</a></li>' for a,b in toc)}</ul></nav><p class="small">Suggested teaching time<br><strong>{t['time']}</strong></p><p class="small">Timing, task steps and quantities are classroom suggestions, not NZQA grade requirements.</p>{link(standard_url(t),'Read the standard (PDF)','text-action')}</aside><article class="sheet-body"><section id="brief"><h2>The brief</h2><p class="proposition">{e(t['theme'])}</p><p>{e(t['brief'])}</p><h3>Materials & preparation</h3><p>{e(t['materials'])}</p><p>Use your own drawings and photographs as starting points. Record sources and seek permission for people, places and culturally significant material. Discuss tikanga and context with your teacher where relevant.</p>{ext}</section><section id="artists"><h2>Artist connections</h2><p>Choose the connections that serve your intention. The contemporary models offer different approaches; select a relevant comparison rather than studying every artist. These works are references, not assessment exemplars.</p><p class="model-brief">{e(t["artist_prompt"])}</p><ul class="artist-connections">{''.join(artist_connection(k) for k in t['artists'])}</ul><h3>Historical comparison</h3>{figure(first_image,'study-image')}<p class="small">Artwork reproduction rights and assessment permission are different. A reusable image on this site is not automatically suitable for your assessed portfolio. Read the {link('teacher.html#external-conditions','external conditions')}.</p></section><section id="studio"><h2>Studio sequence</h2><p>Use this as a flexible route through the learning. Let the work suggest the next move.</p><ol class="studio-steps">{phases}</ol><div class="checkpoint"><h3>A useful studio conversation</h3><p>Put two related works side by side. Describe what changed, show the evidence and explain what you will investigate next. Invite feedback, then make your own decision.</p></div></section><section id="evidence"><h2>Evidence checklist</h2><p>Use this to review your work. Completing the list does not guarantee a grade.</p><p class="check-progress js-only" role="status">0 of {len(t['evidence'])} evidence checks complete</p><ul class="evidence-list">{checklist}</ul><h3>Presentation & submission</h3>{submission(t)}</section><section id="grades"><h2>What changes between grades?</h2><p>Student-friendly guidance adapted from the standard. The whole body of relevant evidence determines the grade; the examples below illustrate possibilities.</p><table class="grade-table"><caption class="sr-only">Grade distinctions for AS{t['as_id']}</caption><thead><tr><th scope="col">Grade</th><th scope="col">What the evidence needs to show</th></tr></thead><tbody>{grades}</tbody></table><p class="source-note">Authority: {link(standard_url(t),'NZQA AS'+str(t['as_id'])+' achievement criteria and explanatory notes (PDF)')}.</p><div class="watch-for"><h3>Watch for</h3><p>{e(t['watch'])}</p></div></section><section id="reflect"><h2>Pause & reflect</h2><p class="reflection-question">{e(t['reflection'])}</p><div class="notes-area"><label for="intention">My working intention</label><textarea id="intention" data-save="intention" rows="3" placeholder="What am I trying to communicate or investigate?"></textarea><label for="next-decision">My next decision</label><textarea id="next-decision" data-save="next-decision" rows="4" placeholder="Refer to something visible in your work. What will you test or change?"></textarea><p class="small" id="storage-status" role="status">These optional working notes belong to you. This website does not submit assessment evidence.</p><p class="js-only small">Notes and checkboxes can be saved in this browser. On a shared device, clear them before leaving.</p><button class="text-button js-only clear-notes" type="button">Clear this sheet’s notes & checks</button></div></section><section id="teacher-notes" class="teacher-notes"><h2>Teacher notes</h2><details open><summary>Planning, assessment & differentiation</summary><div><p>{e(t['teacher'])}</p>{'<p>'+link('lessons-1-2.html','Open the printable 50-minute lesson plans for 1.2')+'</p>' if ref=='1.2' else ''}<h3>Support and stretch</h3><p>For teaching practice, reduce the number of simultaneous choices, model one material process and invite oral discussion alongside drawing. Offer vocabulary prompts and accessible media. To extend the learning, ask students to compare alternatives, justify a rejection or investigate a consequence of their own decision. Adapt assessed support to the standard’s conditions and any approved arrangements.</p><h3>Before issuing the task</h3><p>Set local start and finish dates, agree available materials and check the current standard, conditions and exemplars. Use school authenticity processes and your normal moderation procedures. Adjust this brief to the class and context; it has not been quality assured by NZQA.</p><div class="teacher-fields"><p>Assessment window: <span></span></p><p>Teacher / class: <span></span></p><p>Checkpoint dates: <span></span></p></div></div></details></section><section id="sources" class="sources"><h2>NZQA sources for this sheet</h2><ul><li>{link(standard_url(t),'AS'+str(t['as_id'])+' · official achievement standard (PDF)')}</li><li>{link(exemplar_url(t),'NZQA exemplars and assessment resources')}</li>{'<li>'+link(spec_url(t),'2026 external assessment specifications (PDF)')+'</li>' if t['assessment']=='External' else ''}<li>{link('https://www2.nzqa.govt.nz/ncea/subjects/select-subject/visual-arts/nmr/','Visual Arts National Moderator’s Report')}</li></ul><p class="small">Checked {CHECKED}. This original task sheet interprets NZQA requirements for a painting classroom; official NZQA documents govern assessment.</p></section></article></div><nav class="sheet-next" aria-label="Other tasks at this level">{''.join(link(filename(x),f"{x['ref']} · {e(x['title'])}",'current' if x['ref']==ref else '') for x in TASKS if level(x)==i)}</nav></main>'''
 write(filename(t),f"{ref} · {t['title']}",body,current=str(i),bodyclass=f'theme-{i}',description=f"NCEA {ref} · AS{t['as_id']}. {t['short']}. Printable painting task sheet, artist links, grade guidance and teacher notes.")
artist_sections=''
for group_id, group_title, group_intro, keys in ARTIST_GROUPS:
 entries=''
 for key in keys:
  a=ARTISTS[key]
  related=[t for t in TASKS if key in t['artists']]
  used_in='<p class="small artist-tasks">Use with: '+ ' · '.join(link(filename(t),t['ref']) for t in related)+'</p>' if related else ''
  source=link(a['url'],e(a.get('source_label','Visit the artist resource')),'text-action')
  film='<p class="small">'+link(a['video'],'Watch the artist / studio film')+'</p>' if a.get('video') else ''
  experiment='<p class="artist-investigation"><strong>Painting investigation:</strong> '+e(a['investigation'])+'</p>' if a.get('investigation') else '<p class="small">Compare a pictorial decision here with a contemporary model, then test a related method using your own subject.</p>'
  identity=f'''<div class="artist-identity"><h3>{e(a['name'])}</h3><p class="artist-place">{e(a['place'])}</p>{used_in}</div>'''
  exploration=f'''<div class="artist-exploration"><p>{e(a['focus'])}</p>{experiment}<p>{source}</p>{film}</div>'''
  if a.get('image'):
   entries+=f'''<article class="artist-study" id="{key}">{figure(key)}<div>{identity}{exploration}</div></article>'''
  else:
   entries+=f'''<article class="artist-study artist-study-text" id="{key}">{identity}{exploration}</article>'''
 index='<nav class="artist-index group-artist-index" aria-label="'+e(group_title)+'">'+''.join(link('#'+k,e(ARTISTS[k]['name'])) for k in keys)+'</nav>'
 artist_sections+=f'''<section class="artist-group" id="{group_id}"><div class="artist-group-intro"><h2>{e(group_title)}</h2><p>{e(group_intro)}</p>{index}</div>{entries}</section>'''
group_links=''.join(link('#'+gid,e(title)) for gid,title,intro,keys in ARTIST_GROUPS)
write('artists.html','Artist connections',f'''<main id="main"><div class="page-intro"><h1>Learn to look.<br>Then look again.</h1><p class="lead">Contemporary Māori, Aotearoa and international artist models, alongside historical connections. Follow an idea, investigate its context and make your own response.</p><nav class="artist-index" aria-label="Artist groups">{group_links}</nav></div><div class="artist-directory">{artist_sections}</div><section class="section reading-section" id="image-rights"><h2>Images, context & credit</h2><p>The three artwork images reproduced on this site have a CC0 or No Known Copyright Restrictions statement at the linked source. Each caption names the artist, work, collection and rights source. Other artists link directly to resources showing their works and context. Contemporary artwork images remain at their source where a reproduction licence has not been confirmed.</p><p>Image licences do not override assessment conditions. In particular, the 2026 Level 1 and Level 2 external portfolios prohibit appropriated imagery. Use artist works for looking and discussion; generate your own source imagery for the painting tasks.</p><p>Contemporary Māori art includes distinct, evolving practices, not one shared look. Read each artist’s relationship to whakapapa, whenua, people and materials. Learn from pictorial decisions without treating culturally significant imagery or knowledge as a collection of motifs to copy. Discuss context and appropriate engagement with your teacher and relevant knowledge holders.</p><p>Painting investigations on this site are original teaching suggestions. The linked sources provide the artists’ works and contexts; the artists have not endorsed these tasks.</p><p>Artist references checked {CHECKED}. Fonts: Bricolage Grotesque and DM Sans, distributed under the SIL Open Font License. {link('assets/FONT-LICENSES.txt','View font licences')}.</p></section></main>''',current='artists')
standards_rows=''.join(f'<tr><th scope="row">{link(filename(t),t["ref"])}</th><td>{link(standard_url(t),"AS"+str(t["as_id"])+" · v"+str(t["version"]))}</td><td>{t["credits"]}</td><td>{t["assessment"]}</td></tr>' for t in TASKS)
write('teacher.html','For teachers',f'''<main id="main"><div class="page-intro"><h1>Room for your<br>teaching practice.</h1><p class="lead">A practical starting point for a Painting programme, with assessment distinctions made visible.</p></div><div class="teacher-reading"><section id="lesson-plans"><h2>Printable lesson plans</h2><p>Teacher plans organised by standard, starting with 1.2. Open the complete sequence or choose an individual lesson. Every plan includes a learning intention, preparation, a timed classroom sequence, support and extension, and checks for learning.</p><h3>1.2 · One place, one painting</h3><p>AS91913 · Twelve 50-minute lesson plans, with repeatable studio sessions for an adaptable 8–10 week unit. Each lesson prints on two A4 pages; the complete pack includes a two-page unit overview.</p><p>{link('lessons-1-2.html','Open the 1.2 lesson plans','button button-dark')}</p><p><a href="print/lessons-1-2.pdf" download>Download the complete lesson pack (PDF, 26 pages)</a> · {link('task-1-2.html','Student task sheet')}</p></section><section><h2>What these resources are</h2><p>Original, adaptable teaching briefs for nine standards. Each sheet contains one assessment focus, artist connections, a studio sequence, an evidence checklist and a student-friendly grade guide. These resources are independent and have not been quality assured or endorsed by NZQA.</p><p>The grade guides paraphrase the official criteria. Workload, timings and activity suggestions are teaching decisions, not NZQA thresholds or guaranteed routes to a grade. Confirm the suitability of the task and local assessment conditions before issuing it.</p><p>For the classroom: open a level overview, select a sheet and use <strong>Print / save as PDF</strong>. The print view removes navigation and leaves out teacher notes unless you select the option to include them. Print on A4 using the browser’s default margins. Artwork colour is useful but the text and grade labels also work in monochrome.</p></section><section><h2>A programme, not a production line</h2><p>Teach conventions and inquiry strategies, then leave room for students to choose their subject, methods and next steps. Demonstrations and formative conversations are most useful when they increase independence. Keep the assessed evidence student-led.</p><p>At Level 1, 1.2 is a substantial single resolved artwork; 1.3 focuses on developmental inquiry; 1.4 concerns a finished related series. Allow 1.2 the production scope it needs. At Levels 2 and 3, practical drawing includes painting and other visual thinking methods.</p><p>Plan integrated teaching where useful, but identify which evidence supports each standard. Do not assume completing one automatically meets another. Maintain separate, defensible judgements and normal internal moderation procedures.</p></section><section id="external-conditions"><h2>External assessment conditions</h2><p>For the 2026 Level 1 and Level 2 externals, NZQA excludes appropriated imagery and automatically generated content from candidate submissions. Teach with the linked artist references, but ask students to produce their own imagery and words. {link(SPEC+'91914-spc-2026.pdf','Level 1 conditions (PDF)')} · {link(SPEC+'91321-spc-2026.pdf','Level 2 conditions (PDF)')}.</p><p>The 2026 Level 3 Painting rules require original thinking, acknowledgement of incorporated imagery and disclosure of generative AI use. Recognised appropriation strategies have specific conditions; they are not permission to present a copied artwork as original. These task sheets use student-generated source imagery. {link(SPEC+'91456-spc-2026.pdf','Level 3 conditions (PDF)')}.</p><p>Use the studio sequences for teaching and preparation. They are not prescribed assessed response templates. During assessment, restrict conferencing, scaffolding and assistance to what NZQA permits; students must make the choices and produce the evidence. Consult the annual conditions directly, including authenticity requirements.</p><p>School verification and submission practices differ by level. See the presentation notes within each external sheet and the current {link('https://www2.nzqa.govt.nz/ncea/subjects/past-exams-and-exemplars/visual-arts/','NZQA Visual Arts resource hub')}. The 2026 format notes are reference information, not confirmation of requirements for 2027 or a later year.</p></section><section><h2>Make the resource work for your class</h2><p>Negotiate context, materials and scale. Use accessible water-based media where appropriate, discuss safe studio practice and follow your school procedures. Adjust teaching pace and access arrangements to students’ needs without replacing the evidence the standard requires.</p><p>Give students permission to investigate their own experiences. Work with local knowledge and relationships when engaging with culturally significant content; consult appropriate people rather than assigning motifs for decoration.</p><h3>Browser notes and shared devices</h3><p>Each sheet can retain optional working notes and checks in browser storage. There are no accounts, forms sent to a server or assessment uploads. On a shared device, use the clear control before leaving. Local storage can be unavailable or cleared by the browser; it is not a backup. Print or copy any notes you want to keep.</p><h3>Adapting the source files</h3><p>The site is plain HTML, CSS and JavaScript. Edit the finished HTML directly, or update <code>content.py</code> and run <code>python3 build.py</code> to regenerate the pages. The print design is in <code>dist/assets/site.css</code>. Keep NZQA references and image credits with adapted material.</p></section><section id="sources" class="sources"><h2>Standards & primary sources</h2><p>Checked {CHECKED}. Level 1 uses the current Visual Arts standards, with painting activities. Levels 2 and 3 use the painting-specific standards. The linked older publication-year PDFs remain the referenced version 2 standards; the annual specifications are separate documents.</p><div class="table-wrap"><table class="source-table"><caption>Standards covered by this resource</caption><thead><tr><th scope="col">Reference</th><th scope="col">NZQA standard</th><th scope="col">Credits</th><th scope="col">Assessment</th></tr></thead><tbody>{standards_rows}</tbody></table></div><h3>Assessment guidance</h3><ul><li>{link(NZQA,'Visual Arts exemplars, schedules and assessment reports')}</li><li>{link('https://www2.nzqa.govt.nz/ncea/subjects/select-subject/visual-arts/nmr/','Visual Arts National Moderator’s Report')}</li><li>{link(SPEC+'91914-spc-2026.pdf','2026 Level 1 assessment specifications (PDF)')}</li><li>{link(SPEC+'91321-spc-2026.pdf','2026 Level 2 assessment specifications (PDF)')}</li><li>{link(SPEC+'91456-spc-2026.pdf','2026 Level 3 assessment specifications (PDF)')}</li><li>{link('https://www2.nzqa.govt.nz/assets/NCEA/Subject-pages/Visual-Arts/Visual-Arts-L1-and-L2-Submission-Instructions.pdf','NZQA Level 1 and 2 submission instructions (PDF; check annual version)')}</li><li>{link('https://www2.nzqa.govt.nz/ncea/ncea-for-teachers-and-schools/assessor-support/catalogue/visual-arts/','NZQA Visual Arts assessor support and Pūtake')}</li></ul><p>Artist and image sources are credited beside each reference on the {link('artists.html','artist connections page')}.</p></section></div></main>''',current='teacher')
build_lesson_pages(write, standard_url, exemplar_url, next(t for t in TASKS if t['ref']=='1.2'), ARTISTS)
print(f'Built {len(list(OUT.glob("*.html")))} HTML pages.')
